example_solution:
module main

fn to_rna(dna string) string {
	replace_vals := ['G', 'C', 'C', 'G', 'T', 'A', 'A', 'U']
	return dna.replace_each(replace_vals)
}

test_code:
module main

fn test_empty_rna() {
	assert to_rna('') == ''
}

fn test_cytosine_to_guanine() {
	assert to_rna('C') == 'G'
}

fn test_guanine_to_cytosine() {
	assert to_rna('G') == 'C'
}

fn test_thymine_to_adenine() {
	assert to_rna('T') == 'A'
}

fn test_adenine_to_uracial() {
	assert to_rna('A') == 'U'
}

fn test_rna_complement() {
	assert to_rna('ACGTGGTCTTAA') == 'UGCACCAGAAUU'
}
